/// <summary>
/// Tests the encryption of data setup values for one environment: encrypting and decrypting, the binding of a value to its
/// line, locking the private key with the platform encryption, enrolments as text and as ZIP file, and executing encrypted
/// lines in the right and in the wrong environment.
/// </summary>
/// <remarks>
/// Environment EDSENC has the URL of the environment the tests run in and the key of this environment, so its encrypted lines
/// can be executed here. EDSENC2 has the same key but another URL, like a database copy where the setup of another
/// environment is executed. The encrypted value is written to the client secret of EDSENC itself, through its edit method.
/// </remarks>
[SysTestTarget(classStr(OLK_EnvironmentDataSetupCrypto), UtilElementType::Class),
 SysTestTransaction(TestTransactionMode::None)]
class OLK_EnvironmentDataSetupEncryptionTest extends SysTestCase
{
    public const str EnvironmentId      = 'EDSENC';
    public const str OtherEnvironmentId = 'EDSENC2';
    public const str Secret             = 'EDS secret value äöü 123';
    public const str Binding            = 'edsenc|dat|custgroup|editsecret|42';
    public const str PlainValue         = 'EDS value for the sandbox';
}

Method.Source:
public void setUp()
{
    OLK_EnvironmentDataSetupEnrolment enrolment;

    super();

    ttsbegin;
    OLK_EnvironmentDataSetupTestHelper::ensureEnvironment(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, 'Encryption tests', 'https://' + OLK_EnvironmentDataSetupKeyManager::currentHost());
    OLK_EnvironmentDataSetupTestHelper::ensureEnvironment(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId, 'Encryption tests, other URL');
    ttscommit;

    OLK_EnvironmentDataSetupTestHelper::clearEnvironmentLines(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);
    OLK_EnvironmentDataSetupTestHelper::clearEnvironmentLines(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId);

    enrolment = OLK_EnvironmentDataSetupKeyManager::localEnrolment();
    OLK_EnvironmentDataSetupKeyManager::applyEnrolment(OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId), enrolment, true);

    // EDSENC2 gets the same key, but its URL is not this environment.
    ttsbegin;
    OLK_EnvironmentDataSetupTable other = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId, true);
    other.PublicKey         = enrolment.parmPublicKey();
    other.LockedPrivateKey  = enrolment.parmLockedPrivateKey();
    other.KeyFingerprint    = enrolment.parmFingerprint();
    other.update();
    ttscommit;
}

[SysTestMethod]
public void testEncryptDecryptRoundTrip()
{
    container   keyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    str         cipherText = OLK_EnvironmentDataSetupCrypto::encrypt(conPeek(keyPair, 1), OLK_EnvironmentDataSetupEncryptionTest::Secret, OLK_EnvironmentDataSetupEncryptionTest::Binding);

    this.assertFalse(strScan(cipherText, OLK_EnvironmentDataSetupEncryptionTest::Secret, 1, strLen(cipherText)) > 0, 'The cipher text contains the value.');
    this.assertEquals(OLK_EnvironmentDataSetupEncryptionTest::Secret,
        OLK_EnvironmentDataSetupCrypto::decrypt(conPeek(keyPair, 2), cipherText, OLK_EnvironmentDataSetupEncryptionTest::Binding),
        'The value was not decrypted.');
    this.assertNotEqual(cipherText,
        OLK_EnvironmentDataSetupCrypto::encrypt(conPeek(keyPair, 1), OLK_EnvironmentDataSetupEncryptionTest::Secret, OLK_EnvironmentDataSetupEncryptionTest::Binding),
        'Encrypting the same value twice gave the same cipher text.');
}

[SysTestMethod]
public void testOtherBindingFails()
{
    container   keyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    str         cipherText = OLK_EnvironmentDataSetupCrypto::encrypt(conPeek(keyPair, 1), OLK_EnvironmentDataSetupEncryptionTest::Secret, OLK_EnvironmentDataSetupEncryptionTest::Binding);

    this.assertFalse(this.canDecrypt(conPeek(keyPair, 2), cipherText, OLK_EnvironmentDataSetupEncryptionTest::Binding + 'x'),
        'A value was decrypted for another line.');
}

[SysTestMethod]
public void testTamperedCipherTextFails()
{
    container   keyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    str         cipherText = OLK_EnvironmentDataSetupCrypto::encrypt(conPeek(keyPair, 1), OLK_EnvironmentDataSetupEncryptionTest::Secret, OLK_EnvironmentDataSetupEncryptionTest::Binding);
    int         pos = strLen(cipherText) - 50;
    str         tampered = subStr(cipherText, 1, pos - 1) + (subStr(cipherText, pos, 1) == 'A' ? 'B' : 'A') + subStr(cipherText, pos + 1, strLen(cipherText) - pos);

    this.assertFalse(this.canDecrypt(conPeek(keyPair, 2), tampered, OLK_EnvironmentDataSetupEncryptionTest::Binding),
        'A changed cipher text was decrypted.');
}

[SysTestMethod]
public void testOtherKeyFails()
{
    container   keyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    container   otherKeyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    str         cipherText = OLK_EnvironmentDataSetupCrypto::encrypt(conPeek(keyPair, 1), OLK_EnvironmentDataSetupEncryptionTest::Secret, OLK_EnvironmentDataSetupEncryptionTest::Binding);

    this.assertFalse(this.canDecrypt(conPeek(otherKeyPair, 2), cipherText, OLK_EnvironmentDataSetupEncryptionTest::Binding),
        'A value was decrypted with the key of another environment.');
}

[SysTestMethod]
public void testLockedKeyUnlocksHere()
{
    container               keyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    OLK_EdsEncryptedBlob    lockedKey = OLK_EnvironmentDataSetupCrypto::lockPrivateKey(conPeek(keyPair, 2));
    str                     lockedText = OLK_EnvironmentDataSetupCrypto::blobToBase64(lockedKey);

    this.assertFalse(strScan(lockedText, 'RSAKeyValue', 1, strLen(lockedText)) > 0, 'The locked key is readable.');
    this.assertEquals(conPeek(keyPair, 2), OLK_EnvironmentDataSetupCrypto::unlockPrivateKey(OLK_EnvironmentDataSetupCrypto::base64ToBlob(lockedText)),
        'The locked key did not unlock after a round trip as text.');
    this.assertEquals(conPeek(keyPair, 1), OLK_EnvironmentDataSetupCrypto::publicKeyOf(conPeek(keyPair, 2)), 'The public key of the private key differs.');
    this.assertEquals('', OLK_EnvironmentDataSetupCrypto::unlockPrivateKey(conNull()), 'An empty locked key was unlocked.');
}

[SysTestMethod]
public void testLocalEnrolmentIsStable()
{
    OLK_EnvironmentDataSetupEnrolment first  = OLK_EnvironmentDataSetupKeyManager::localEnrolment();
    OLK_EnvironmentDataSetupEnrolment second = OLK_EnvironmentDataSetupKeyManager::localEnrolment();

    this.assertEquals(OLK_EnvironmentDataSetupKeyManager::currentHost(), first.parmHostName(), 'The enrolment is not for this environment.');
    this.assertEquals(first.parmFingerprint(), second.parmFingerprint(), 'The key of this environment changed between two calls.');
    this.assertEquals(64, strLen(first.parmFingerprint()), 'The fingerprint is not a SHA-256 in hexadecimal.');
}

[SysTestMethod]
public void testEnrolmentTextRoundTrip()
{
    OLK_EnvironmentDataSetupEnrolment enrolment = OLK_EnvironmentDataSetupKeyManager::localEnrolment();
    OLK_EnvironmentDataSetupEnrolment fromText  = OLK_EnvironmentDataSetupEnrolment::fromText(enrolment.toText());
    OLK_EnvironmentDataSetupEnrolment fromTransport = OLK_EnvironmentDataSetupEnrolment::fromTransportText('"' + enrolment.toTransportText() + '"');
    str transport = enrolment.toTransportText();

    this.assertEquals(enrolment.parmFingerprint(), fromText.parmFingerprint(), 'The fingerprint changed in the text.');
    this.assertEquals(enrolment.parmPublicKey(), fromText.parmPublicKey(), 'The public key changed in the text.');
    this.assertTrue(OLK_EnvironmentDataSetupKeyManager::canUnlock(fromText.parmPublicKey(), fromText.parmLockedPrivateKey()), 'The locked key from the text cannot be unlocked.');
    this.assertEquals(enrolment.parmFingerprint(), fromTransport.parmFingerprint(), 'The fingerprint changed in the service response.');
    this.assertFalse(strScan(transport, '/', 1, strLen(transport)) || strScan(transport, '+', 1, strLen(transport)) || strScan(transport, '=', 1, strLen(transport)),
        'The service response text needs JSON escaping.');
}

[SysTestMethod]
public void testChangedEnrolmentIsRejected()
{
    OLK_EnvironmentDataSetupEnrolment   enrolment = OLK_EnvironmentDataSetupKeyManager::localEnrolment();
    container                           otherKeyPair = OLK_EnvironmentDataSetupCrypto::generateKeyPair();
    str                                 text = strReplace(enrolment.toText(), enrolment.parmPublicKey(), conPeek(otherKeyPair, 1));
    boolean                             rejected;

    try
    {
        OLK_EnvironmentDataSetupEnrolment::fromText(text);
    }
    catch (Exception::Error)
    {
        rejected = true;
    }

    this.assertTrue(rejected, 'An enrolment with a replaced public key was accepted.');
}

[SysTestMethod]
public void testEnrolmentFileRoundTrip()
{
    OLK_EnvironmentDataSetupEnrolment enrolment = OLK_EnvironmentDataSetupKeyManager::localEnrolment();
    OLK_EnvironmentDataSetupEnrolment fromFile  = OLK_EnvironmentDataSetupKeyManager::readEnrolmentFile(OLK_EnvironmentDataSetupKeyManager::exportEnrolmentFile());

    this.assertEquals(enrolment.parmHostName(), fromFile.parmHostName(), 'The host name changed in the ZIP file.');
    this.assertEquals(enrolment.parmFingerprint(), fromFile.parmFingerprint(), 'The fingerprint changed in the ZIP file.');
    this.assertTrue(OLK_EnvironmentDataSetupKeyManager::canUnlock(fromFile.parmPublicKey(), fromFile.parmLockedPrivateKey()), 'The locked key from the ZIP file cannot be unlocked.');
}

[SysTestMethod]
public void testEnrolmentForOtherHostIsRejected()
{
    boolean rejected;

    try
    {
        OLK_EnvironmentDataSetupKeyManager::applyEnrolment(
            OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId),
            OLK_EnvironmentDataSetupKeyManager::localEnrolment(),
            true);
    }
    catch (Exception::Error)
    {
        rejected = true;
    }

    this.assertTrue(rejected, 'The key of this environment was stored for an environment with another URL.');
}

[SysTestMethod]
public void testNormalizeHost()
{
    this.assertEquals('uat.sandbox.operations.dynamics.com', OLK_EnvironmentDataSetupKeyManager::normalizeHost('https://UAT.sandbox.operations.dynamics.com/?cmp=USMF'), 'A full URL was not reduced to its host.');
    this.assertEquals('uat.sandbox.operations.dynamics.com', OLK_EnvironmentDataSetupKeyManager::normalizeHost(' uat.sandbox.operations.dynamics.com '), 'A host without https:// was not accepted.');
    this.assertEquals('', OLK_EnvironmentDataSetupKeyManager::normalizeHost(''), 'An empty URL gave a host.');
}

[SysTestMethod]
public void testEncryptedLineStoresOnlyCipherText()
{
    OLK_EnvironmentDataSetupTrans trans = this.addEncryptedLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);

    this.assertEquals('', trans.Value, 'The value of an encrypted line is stored in plain text.');
    this.assertTrue(trans.CipherText != '', 'The value of an encrypted line was not encrypted.');
    this.assertFalse(strScan(trans.CipherText, OLK_EnvironmentDataSetupEncryptionTest::Secret, 1, strLen(trans.CipherText)) > 0, 'The cipher text contains the value.');
    this.assertEquals(OLK_EnvironmentDataSetupCrypto::ValueMask, trans.editValue(false, ''), 'The form does not mask the encrypted value.');
}

/// <summary>
/// Executing EDSENC here decrypts the value and writes it through the edit method; the log does not contain it.
/// </summary>
[SysTestMethod]
public void testExecuteDecryptsEncryptedLine()
{
    RecId                           fromLog = OLK_EnvironmentDataSetupTestHelper::lastLogRecId();
    OLK_EnvironmentDataSetupTrans   trans = this.addEncryptedLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);
    OLK_EnvironmentDataSetupLog     log;

    OLK_EnvironmentDataSetupTestHelper::execute(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, NoYes::Yes, NoYes::No, NoYes::No);

    log = OLK_EnvironmentDataSetupTestHelper::findLogSince(fromLog, OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EdsLogType::Data, int642Str(trans.RecId));

    this.assertEquals(OLK_EdsLogStatus::OK, log.Status, strFmt('The encrypted line failed: %1', log.ErrorTxt));
    this.assertEquals('', log.Value, 'The encrypted value was written to the log.');
    this.assertEquals(OLK_EnvironmentDataSetupEncryptionTest::Secret,
        OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId).clientSecret(),
        'The decrypted value was not written through the edit method.');
}

/// <summary>
/// EDSENC2 has a URL that is not this environment, so its encrypted lines fail here even with a key that can be unlocked.
/// </summary>
[SysTestMethod]
public void testExecuteInOtherEnvironmentFails()
{
    RecId                           fromLog = OLK_EnvironmentDataSetupTestHelper::lastLogRecId();
    OLK_EnvironmentDataSetupTrans   trans = this.addEncryptedLine(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId);
    OLK_EnvironmentDataSetupLog     log;

    OLK_EnvironmentDataSetupTestHelper::execute(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId, NoYes::Yes, NoYes::No, NoYes::No);

    log = OLK_EnvironmentDataSetupTestHelper::findLogSince(fromLog, OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId, OLK_EdsLogType::Data, int642Str(trans.RecId));

    this.assertEquals(OLK_EdsLogStatus::Error, log.Status, 'An encrypted line was executed in another environment.');
    this.assertEquals('', log.Value, 'The encrypted value was written to the log.');
}

/// <summary>
/// A cipher text copied to a line for another record cannot be decrypted, so it cannot be redirected to a visible field.
/// </summary>
[SysTestMethod]
public void testMovedLineCannotBeDecrypted()
{
    OLK_EnvironmentDataSetupTrans   trans = this.addEncryptedLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);
    str                             privateKey = OLK_EnvironmentDataSetupKeyManager::privateKeyForEnvironment(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);
    str                             cipherText = trans.CipherText;

    trans.RefRecId = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId).RecId;

    this.assertFalse(this.canDecrypt(privateKey, cipherText, trans.encryptionBinding()), 'A value was decrypted for another record.');
}

/// <summary>
/// A plain line, as the Personalize pop-up creates it, keeps its field when it is marked as encrypted, and its value becomes
/// cipher text that only the key of the environment can read.
/// </summary>
[SysTestMethod]
public void testMarkingPlainLineEncryptsItsValue()
{
    OLK_EnvironmentDataSetupTrans   trans = this.addPlainDescriptionLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EnvironmentDataSetupEncryptionTest::PlainValue);
    str                             privateKey = OLK_EnvironmentDataSetupKeyManager::privateKeyForEnvironment(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);

    this.markEncrypted(trans);

    this.assertEquals(fieldNum(OLK_EnvironmentDataSetupTable, Description), trans.FieldId, 'The line lost its field.');
    this.assertEquals('', trans.EncryptedMethodName, 'The line got an edit method.');
    this.assertEquals('', trans.Value, 'The plain value stayed on the line.');
    this.assertEquals(OLK_EnvironmentDataSetupCrypto::ValueMask, trans.editValue(false, ''), 'The form does not mask the value.');
    this.assertEquals(OLK_EnvironmentDataSetupEncryptionTest::PlainValue, OLK_EnvironmentDataSetupCrypto::decrypt(privateKey, trans.CipherText, trans.encryptionBinding()),
        'The cipher text does not hold the value.');

    OLK_EnvironmentDataSetupTrans stored;

    select firstonly stored where stored.RecId == trans.RecId;

    this.assertEquals('', stored.Value, 'The plain value was stored.');
    this.assertEquals(trans.CipherText, stored.CipherText, 'The cipher text was not stored.');
}

/// <summary>
/// Executing writes the decrypted value to a normal field without an edit method; the log holds neither it nor the old value.
/// </summary>
[SysTestMethod]
public void testExecuteWritesEncryptedValueToPlainField()
{
    RecId                           fromLog = OLK_EnvironmentDataSetupTestHelper::lastLogRecId();
    OLK_EnvironmentDataSetupTrans   trans = this.addPlainDescriptionLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EnvironmentDataSetupEncryptionTest::PlainValue);
    OLK_EnvironmentDataSetupLog     log;

    this.markEncrypted(trans);

    OLK_EnvironmentDataSetupTestHelper::execute(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, NoYes::Yes, NoYes::No, NoYes::No);

    log = OLK_EnvironmentDataSetupTestHelper::findLogSince(fromLog, OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EdsLogType::Data, int642Str(trans.RecId));

    this.assertEquals(OLK_EdsLogStatus::OK, log.Status, strFmt('The encrypted line failed: %1', log.ErrorTxt));
    this.assertEquals('', log.Value, 'The encrypted value was written to the log.');
    this.assertEquals('', log.ValueOrig, 'The old value of the field was written to the log.');
    this.assertEquals(OLK_EnvironmentDataSetupEncryptionTest::PlainValue, OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId).Description,
        'The decrypted value was not written to the field.');

    // Restore the description the setup of this test class expects.
    ttsbegin;
    OLK_EnvironmentDataSetupTable target = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId, true);
    target.Description = 'Encryption tests, other URL';
    target.update();
    ttscommit;
}

/// <summary>
/// A value for a field cannot be moved to another field of the same record, and lines with an edit method keep their binding,
/// so values encrypted before fields were supported stay valid.
/// </summary>
[SysTestMethod]
public void testFieldIsPartOfBindingWithoutMethod()
{
    OLK_EnvironmentDataSetupTrans   trans = this.addPlainDescriptionLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EnvironmentDataSetupEncryptionTest::PlainValue);
    OLK_EnvironmentDataSetupTrans   methodLine = this.addEncryptedLine(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId);
    str                             privateKey = OLK_EnvironmentDataSetupKeyManager::privateKeyForEnvironment(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);
    str                             cipherText;

    this.markEncrypted(trans);
    cipherText = trans.CipherText;

    trans.FieldId = fieldNum(OLK_EnvironmentDataSetupTable, EnvironmentUrl);

    this.assertFalse(this.canDecrypt(privateKey, cipherText, trans.encryptionBinding()), 'A value was decrypted for another field.');
    this.assertEquals(strLwr(strFmt('%1||%2|%3|%4', OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId, tableStr(OLK_EnvironmentDataSetupTable),
        tableMethodStr(OLK_EnvironmentDataSetupTable, editClientSecret), int642Str(methodLine.RefRecId))),
        methodLine.encryptionBinding(), 'The binding of lines with an edit method changed.');
}

/// <summary>
/// A line cannot be marked as encrypted when its environment has no key or its value does not fit the field, and the plain
/// value stays as it was.
/// </summary>
[SysTestMethod]
public void testMarkingIsRefused()
{
    OLK_EnvironmentDataSetupTrans trans;

    this.assertEquals('', OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupTestHelper::TestEnvironmentId).PublicKey, 'The test environment has a key.');

    trans.EnvironmentId  = OLK_EnvironmentDataSetupTestHelper::TestEnvironmentId;
    trans.RefTableId     = tableNum(OLK_EnvironmentDataSetupTable);
    trans.RefRecId       = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId).RecId;
    trans.FieldId        = fieldNum(OLK_EnvironmentDataSetupTable, Description);
    trans.Value          = OLK_EnvironmentDataSetupEncryptionTest::PlainValue;
    trans.EncryptedField = NoYes::Yes;
    this.assertFalse(trans.validateField(fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField)), 'A line was marked as encrypted without a key.');

    trans.EnvironmentId = OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId;
    trans.FieldId       = fieldNum(OLK_EnvironmentDataSetupTable, MasterEnvironment);
    trans.Value         = 'NotAnEnumValue';
    this.assertFalse(trans.validateField(fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField)), 'A value that does not fit the field was accepted.');
    this.assertEquals('NotAnEnumValue', trans.Value, 'The refused value was changed.');
    this.assertEquals('', trans.CipherText, 'The refused value was encrypted.');

    trans.Value = 'Yes';
    this.assertTrue(trans.validateField(fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField)), 'A valid enum value was refused.');
}

/// <summary>
/// A value typed on an encrypted line without an edit method is checked against the field, and enum labels are stored as
/// their number, as on a plain line.
/// </summary>
[SysTestMethod]
public void testTypedValueIsCheckedBeforeEncrypting()
{
    OLK_EnvironmentDataSetupTrans   trans;
    str                             privateKey = OLK_EnvironmentDataSetupKeyManager::privateKeyForEnvironment(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);
    boolean                         refused;

    trans.EnvironmentId     = OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId;
    trans.RefTableId        = tableNum(OLK_EnvironmentDataSetupTable);
    trans.RefRecId          = 42;
    trans.FieldId           = fieldNum(OLK_EnvironmentDataSetupTable, MasterEnvironment);
    trans.EncryptedField    = NoYes::Yes;

    try
    {
        trans.editValue(true, 'NotAnEnumValue');
    }
    catch (Exception::Error)
    {
        refused = true;
    }

    this.assertTrue(refused, 'A value that does not fit the field was encrypted.');
    this.assertEquals('', trans.CipherText, 'The refused value was encrypted.');

    trans.editValue(true, 'Yes');

    this.assertEquals('1', OLK_EnvironmentDataSetupCrypto::decrypt(privateKey, trans.CipherText, trans.encryptionBinding()), 'The enum value was not stored as its number.');
}

/// <summary>
/// A line that is no longer encrypted has no value, because this environment cannot decrypt it. It keeps its field.
/// </summary>
[SysTestMethod]
public void testUnmarkingClearsTheValue()
{
    OLK_EnvironmentDataSetupTrans trans = this.addPlainDescriptionLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EnvironmentDataSetupEncryptionTest::PlainValue);

    this.markEncrypted(trans);

    trans.EncryptedField = NoYes::No;
    trans.modifiedField(fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField));

    this.assertEquals('', trans.CipherText, 'The cipher text stayed on a plain line.');
    this.assertEquals('', trans.Value, 'A plain line got a value.');
    this.assertEquals(fieldNum(OLK_EnvironmentDataSetupTable, Description), trans.FieldId, 'The line lost its field.');
}

/// <summary>
/// Encrypt plain values also encrypts a plain value on an encrypted line that has a field and no edit method.
/// </summary>
[SysTestMethod]
public void testEncryptPlainValuesHandlesFieldLines()
{
    OLK_EnvironmentDataSetupTrans   trans = this.addPlainDescriptionLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EnvironmentDataSetupEncryptionTest::PlainValue);
    RecId                           recId = trans.RecId;
    str                             privateKey = OLK_EnvironmentDataSetupKeyManager::privateKeyForEnvironment(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId);

    ttsbegin;
    select firstonly forupdate trans
        where trans.RecId == recId;
    trans.EncryptedField = NoYes::Yes;
    trans.doUpdate();
    ttscommit;

    this.assertEquals(1, OLK_EnvironmentDataSetupKeyManager::encryptPlainValues(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId), 'The line was not encrypted.');

    select firstonly trans
        where trans.RecId == recId;

    this.assertEquals('', trans.Value, 'The plain value stayed on the line.');
    this.assertEquals(OLK_EnvironmentDataSetupEncryptionTest::PlainValue, OLK_EnvironmentDataSetupCrypto::decrypt(privateKey, trans.CipherText, trans.encryptionBinding()),
        'The cipher text does not hold the value.');
}

/// <summary>
/// Adding the field again from the Personalize pop-up does not turn an encrypted line back into a plain one.
/// </summary>
[SysTestMethod]
public void testOverwritingEncryptedLineStaysEncrypted()
{
    OLK_EnvironmentDataSetupTrans   trans = this.addPlainDescriptionLine(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EnvironmentDataSetupEncryptionTest::PlainValue);
    OLK_EnvironmentDataSetupTable   target = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId);
    OLK_EnvironmentDataSetupTrans   overwritten;

    this.markEncrypted(trans);

    overwritten = OLK_EnvironmentDataSetupTrans::createTrans(target, fieldNum(OLK_EnvironmentDataSetupTable, Description),
        OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId, OLK_EdsOverwriteType::Always, '');

    this.assertEquals(trans.RecId, overwritten.RecId, 'A second line was created.');
    this.assertEquals(NoYes::Yes, overwritten.EncryptedField, 'The line is no longer encrypted.');
    this.assertEquals('', overwritten.Value, 'The value was stored in plain text.');
    this.assertTrue(overwritten.CipherText != '', 'The value was not encrypted.');
}

/// <summary>
/// Adds a plain line for the description of EDSENC2, as the Personalize pop-up does.
/// </summary>
private OLK_EnvironmentDataSetupTrans addPlainDescriptionLine(OLK_EdsEnvironmentId _environmentId, str _value)
{
    OLK_EnvironmentDataSetupTrans trans;

    ttsbegin;

    trans.EnvironmentId = _environmentId;
    trans.RefDataAreaId = '';
    trans.RefTableId    = tableNum(OLK_EnvironmentDataSetupTable);
    trans.RefRecId      = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::OtherEnvironmentId).RecId;
    trans.FieldId       = fieldNum(OLK_EnvironmentDataSetupTable, Description);
    trans.Description   = 'Plain test value';
    trans.Value         = _value;
    trans.insert();

    ttscommit;

    return trans;
}

/// <summary>
/// Sets Encrypted field on a line and saves it, as the form does.
/// </summary>
private void markEncrypted(OLK_EnvironmentDataSetupTrans _trans)
{
    RecId recId = _trans.RecId;

    ttsbegin;

    select firstonly forupdate _trans
        where _trans.RecId == recId;

    _trans.EncryptedField = NoYes::Yes;
    this.assertTrue(_trans.validateField(fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField)), 'The line could not be marked as encrypted.');
    _trans.modifiedField(fieldNum(OLK_EnvironmentDataSetupTrans, EncryptedField));
    this.assertTrue(_trans.validateWrite(), 'The encrypted line could not be saved.');
    _trans.update();

    ttscommit;
}

/// <summary>
/// Adds an encrypted line that writes the secret to the client secret of EDSENC through its edit method, entering the value
/// as the form does.
/// </summary>
private OLK_EnvironmentDataSetupTrans addEncryptedLine(OLK_EdsEnvironmentId _environmentId)
{
    OLK_EnvironmentDataSetupTrans trans;

    ttsbegin;

    trans.EnvironmentId         = _environmentId;
    trans.RefDataAreaId         = '';
    trans.RefTableId            = tableNum(OLK_EnvironmentDataSetupTable);
    trans.RefRecId              = OLK_EnvironmentDataSetupTable::find(OLK_EnvironmentDataSetupEncryptionTest::EnvironmentId).RecId;
    trans.EncryptedField        = NoYes::Yes;
    trans.EncryptedMethodName   = tableMethodStr(OLK_EnvironmentDataSetupTable, editClientSecret);
    trans.Description           = 'Encrypted test value';
    trans.editValue(true, OLK_EnvironmentDataSetupEncryptionTest::Secret);
    trans.insert();

    ttscommit;

    return trans;
}

